"""Student accounts: Voter IDs, school student numbers, and the class-list importer.

Every student has TWO different numbers:
  * Voter ID (e.g. V-7KQ3M9)  - the LOGIN username. Generated by BotoKo, random, unique.
                                Stored in the students.student_no column (the old login column).
  * School student number      - student information only (e.g. 23-1-00479). NOT a login.

Nothing in this file touches the database or Flask, so it is easy to test on its own.
"""
import csv
import io
import re
import secrets

# Voter ID: "V-" + 6 characters with no look-alikes (no 0/O, 1/I/L), so it is easy to read
# off a paper slip. 31^6 = ~887 million possibilities, picked at random, so it can't be guessed.
VOTER_ID_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"
VOTER_ID_EXAMPLE = "V-7KQ3M9"
PASSWORD_ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789"

# School student number format. Change ONLY these two lines if your school uses another format.
SCHOOL_NO_PATTERN = r"^\d{2}-\d-\d{5}$"
SCHOOL_NO_EXAMPLE = "23-1-00479"
SCHOOL_NO_RE = re.compile(SCHOOL_NO_PATTERN)

MAX_YEAR = 5
CSV_COLUMNS = ["school_student_no", "full_name", "course", "department", "year", "section"]


def new_voter_id():
    return "V-" + "".join(secrets.choice(VOTER_ID_ALPHABET) for _ in range(6))


def new_password():
    return "".join(secrets.choice(PASSWORD_ALPHABET) for _ in range(8))


def normalize_login(raw):
    """What the student typed -> the Voter ID to look up.

    'v-7kq3m9', 'V7KQ3M9' and ' v 7kq3m9 ' all become 'V-7KQ3M9'. Older usernames
    (e.g. S0001 from before Voter IDs existed) are only uppercased, so they keep working.
    """
    typed = (raw or "").strip().upper()
    compact = re.sub(r"[\s\-]", "", typed)
    if re.fullmatch(r"V[A-Z0-9]{6}", compact):
        return "V-" + compact[1:]
    return typed


def looks_like_school_no(raw):
    return bool(SCHOOL_NO_RE.match((raw or "").strip()))


def group_label(course, year, section):
    """'BSIT', 3, 'A' -> 'BSIT 3-A' (empty if the details are not filled in yet)."""
    if not course or not year or not section:
        return ""
    return f"{course} {year}-{section}"


def clean_details(values):
    """Trim/normalise one student's details and check them.

    values: dict with the CSV_COLUMNS keys (year may be text). Returns (details, errors).
    """
    def text(key):
        return " ".join(str(values.get(key) or "").split())        # trim + collapse spaces

    details = {
        "school_student_no": text("school_student_no"),
        "full_name": text("full_name")[:80],
        "course": text("course").upper()[:30],
        "department": text("department")[:80],
        "section": text("section").upper()[:10],
        "year": None,
    }
    errors = []
    labels = {"school_student_no": "school student number", "full_name": "full name",
              "course": "course", "department": "school/department", "section": "section"}
    for key, label in labels.items():
        if not details[key]:
            errors.append(f"{label} is missing")
    year = text("year")
    if not year:
        errors.append("year is missing")
    elif not year.isdigit() or not 1 <= int(year) <= MAX_YEAR:
        errors.append(f'year must be 1 to {MAX_YEAR} (got "{year}")')
    else:
        details["year"] = int(year)
    if details["school_student_no"] and not SCHOOL_NO_RE.match(details["school_student_no"]):
        errors.append(f'school student number "{details["school_student_no"]}" does not look like '
                      f'{SCHOOL_NO_EXAMPLE}')
    return details, errors


def parse_class_list(text):
    """Pasted lines or a .csv file -> [(line_number, [values...]), ...].

    Format: school_student_no, full_name, course, department, year, section
    The header row is optional. Names with commas must be in quotes ("Dela Cruz, Juan").
    """
    rows = []
    # skipinitialspace: people type ', "Santos, Maria"' with a space before the quote.
    for line_no, values in enumerate(csv.reader(io.StringIO(text), skipinitialspace=True), start=1):
        values = [v.strip() for v in values]
        if not any(values):
            continue                                          # blank line
        if not rows and values[0].lower().replace(" ", "_") in ("school_student_no", "school_no",
                                                                  "student_no", "school_student_number"):
            continue                                          # header row
        rows.append((line_no, values))
    return rows


def check_class_list(rows, existing_numbers):
    """Validate every row of an import.

    existing_numbers: school student numbers already in the database.
    Returns (to_create, skipped, errors):
      to_create - list of details dicts
      skipped   - [(line, school_no)] already have an account (re-uploading a list is safe)
      errors    - [(line, "reason; reason")]  -> if any, NOTHING is created
    """
    to_create, skipped, errors, seen = [], [], [], {}
    for line, values in rows:
        if len(values) != len(CSV_COLUMNS):
            errors.append((line, f"expected {len(CSV_COLUMNS)} values ({', '.join(CSV_COLUMNS)}), "
                                 f"found {len(values)}"))
            continue
        details, problems = clean_details(dict(zip(CSV_COLUMNS, values)))
        number = details["school_student_no"]
        if number and number in seen:
            problems.append(f"school student number {number} is also on line {seen[number]}")
        elif number:
            seen[number] = line
        if problems:
            errors.append((line, "; ".join(problems)))
            continue
        if number in existing_numbers:
            skipped.append((line, number))
        else:
            to_create.append(details)
    return to_create, skipped, errors
